import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{capsule}from'../../core/geometry.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
export function grove(host,index){const id=spec.grove.ids[index],frame=new THREE.Group();frame.name='TypeC to Grove actual '+id+' upright four-contact socket';frame.position.fromArray(spec.grove.positions[index]);frame.rotation.z=-Math.PI/2;host.body.add(frame);const plastic=materials.plastic(0xe9eae4,{roughness:.76}),metal=materials.metal(0xbcbab0,{roughness:.45}),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'TypeC to Grove '+id+' '+n),body=[];
 body.push(box([10,.65,5.2],[0,2.275,-2.6],'full outer wall'));for(const sign of[-1,1]){body.push(box([.65,4.55,5.2],[sign*4.675,-.325,-2.6],'end wall'));body.push(box([1.4,.65,5.2],[sign*3.65,-2.275,-2.6],'latch-side end support'));body.push(box([.6,.5,1.2],[sign*3.1,-1.95,-1.15],'real latch shoulder'));}body.push(box([5.8,.65,1.45],[0,-2.275,-4.475],'recessed latch-side lower bridge'));const floor=box([8.7,3.9,.6],[0,0,-4.9],'deep dielectric socket floor');const contacts=[],tips=[],tails=[];for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(box([.42,.42,3.2],[x,.5,-3],'actual independent metal pin '+(i+1),metal));const tip=mesh(frame,new THREE.SphereGeometry(.21,16,10),metal,[x,.5,-1.4],'TypeC to Grove '+id+' actual rounded contact tip '+(i+1));tips.push(tip);tails.push(box([.42,.42,1.55],[x,.5,-5.375],'PCB solder tail '+(i+1),metal));}
 const pins=[{n:1,name:'S1',color:'white'},{n:2,name:'S2',color:'yellow'},{n:3,name:index?'5V IN':'NC',color:'red'},{n:4,name:index?'GND':'GND print/schematic; NC table,unconfirmed',color:'black'}];const port=host.add(new Port({id,label:index?'OUTPUT CH'+index+' · physical Grove':'INPUT CH · physical signal Grove',connector:'grove',position:spec.grove.positions[index],quaternion:FACE.left,hitSize:[10,1,5.2],pins,pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.5],order:col=>col+1},meta:{role:'visual-connector',face:'front',outward:[0,0,1],physicalRole:index?'output':'input',source:'Own U151 actual front/rear photographs;label S1/S2 numbering only,not live protocol routes',inputGroundConflict:index?undefined:spec.source.inputGroundConflict,scope:'Real socket attachment,documented visible labels and physical four-wire cable pose only.No automatic signal/power forwarding,USB enumeration,I2C/UART,voltage,current or electrical behavior.'}}));return{frame,body,floor,contacts,tips,tails,port};}
export function usb(host){const frame=new THREE.Group();frame.name='TypeC to Grove actual bottom power-only USB-C socket';frame.position.fromArray(spec.usb.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const metal=materials.metal(0xb9bdb6,{roughness:.44}),dark=materials.plastic(0x1e251f,{roughness:.85}),gold=materials.metal(0xbda564,{roughness:.48}),shape=capsule(9,3.2);shape.holes.push(capsule(8.2,2.4,{path:new THREE.Path(),clockwise:true}));const shell=mesh(frame,new THREE.ExtrudeGeometry(shape,{depth:6.3,bevelEnabled:false,curveSegments:48}),metal,[0,0,-6.3],'TypeC to Grove USB-C real hollow metal shell');const rear=mesh(frame,new THREE.BoxGeometry(8.05,2.25,.5),dark,[0,0,-6.05],'TypeC to Grove USB-C deep dielectric rear carrier'),tongue=mesh(frame,new THREE.BoxGeometry(6.3,.55,4.9),dark,[0,0,-3.05],'TypeC to Grove USB-C retained physical tongue'),contacts=[];for(const sign of[-1,1])for(const x of[-2.7,0,2.7])contacts.push(mesh(frame,new THREE.BoxGeometry(.35,.07,3.7),gold,[x,sign*.31,-2.9],'TypeC to Grove USB-C six-terminal power-contact appearance,placement inferred'));const tabs=[];for(const side of[-1,1])tabs.push(mesh(frame,new THREE.BoxGeometry(.7,.6,1.7),metal,[side*4.1,-1.45,-5.4],'TypeC to Grove USB-C fixed metal PCB retention tab'));const port=host.add(new Port({id:'usb',label:'USB-C · DC5V power input appearance',connector:'usb-c',position:spec.usb.position,quaternion:portQuaternion('bottom'),hitSize:[9,1,3.2],pins:['VBUS','CC1','CC2','GND'].map(name=>({name})),meta:{role:'visual-connector',face:'bottom',physicalRole:'power-input',source:'Own U151 CN1 has power/CC/GND/FG only;noUSB data pins shown',scope:'Physical attachment only;no power-state,current,voltage,USB data,enumeration,charging,protocol or electrical behavior'}}));return{frame,shell,rear,tongue,contacts,tabs,port};}
